#include <iostream>
using namespace std;

int main() {
    int n, even = 0, odd = 0;
    cin >> n;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        if (x % 2 == 0) even++;
        else odd++;
    }
    while (odd > even) {
        odd -= 2;
        even += 1;
    }
    if (even > odd + 1) even = odd + 1;
    cout << even + odd << '\n';
    return 0;
}

