        int n = sc.nextInt();
        int even = 0, odd = 0;
        for (int i = 0; i < n; i++) {
            if (sc.nextInt() % 2 == 0) even++;
            else odd++;
        }
        while (odd > even) {
            odd -= 2;
            even += 1;
        }
        if (even > odd + 1) even = odd + 1;
        System.out.println(even + odd);
    }
}

